commit 0bfdb9c18b392eadb4260049548bec6a05e34095
Author: Yukihiro "Matz" Matsumoto <matz@ruby.or.jp>
Date:   Mon Jun 22 21:33:18 2026 +0900

    vm.c: prevent use-after-free when GC runs during a stack realloc

    Growing the callinfo stack (cipush) or the VM value stack
    (stack_extend_alloc) calls mrb_realloc, which can run an incremental GC step
    after it has freed the old buffer but before c->cibase/c->ci (or c->stbase)
    are reassigned. The GC then marks the freed stack through the stale pointers,
    a use-after-free reachable from mrb_load_string on ordinary source
    (ASan-confirmed in #6906). Disable GC across each realloc so no step observes
    the half-updated context.

    Co-authored-by: Claude <noreply@anthropic.com>

diff --git a/src/vm.c b/src/vm.c
index 8245385df..5db6ef684 100644
--- a/src/vm.c
+++ b/src/vm.c
@@ -191,11 +191,17 @@ stack_extend_alloc(mrb_state *mrb, mrb_int room)
   }
 #endif

+  /* Disable GC across the realloc: it frees the old stack before c->stbase is
+     updated, so an incremental GC step triggered from inside the realloc would
+     mark the freed stack (use-after-free). */
+  mrb_bool gc_disabled = mrb->gc.disabled;
+  mrb->gc.disabled = TRUE;
   mrb_value *newstack = (mrb_value*)mrb_realloc(mrb, mrb->c->stbase, sizeof(mrb_value) * size);
   stack_clear(&(newstack[oldsize]), size - oldsize);
   envadjust(mrb, oldbase, newstack);
   mrb->c->stbase = newstack;
   mrb->c->stend = mrb->c->stbase + size;
+  mrb->gc.disabled = gc_disabled;

   /* Raise an exception if the new stack size will be too large,
      to prevent infinite recursion. However, do this only after resizing the stack, so mrb_raise has stack space to work with. */
@@ -383,9 +389,15 @@ cipush(mrb_state *mrb, mrb_int push_stacks, uint8_t cci, struct RClass *target_c
     if (size >= MRB_CALL_LEVEL_MAX) {
       mrb_exc_raise(mrb, mrb_obj_value(mrb->stack_err));
     }
+    /* Disable GC across the realloc: it frees the old callinfo stack before
+       c->cibase/c->ci are updated, so an incremental GC step triggered from
+       inside the realloc would mark the freed stack (use-after-free). */
+    mrb_bool gc_disabled = mrb->gc.disabled;
+    mrb->gc.disabled = TRUE;
     c->cibase = (mrb_callinfo*)mrb_realloc(mrb, c->cibase, sizeof(mrb_callinfo)*size*2);
     c->ci = ci = c->cibase + size;
     c->ciend = c->cibase + size * 2;
+    mrb->gc.disabled = gc_disabled;
   }
   ci->mid = mid;
   CI_PROC_SET(ci, proc);
commit c52faebb7f64cd0d1c51444d7bd22349dece93fa
Author: dearblue <dearblue@gmx.com>
Date:   Tue Mar 24 21:25:46 2026 +0900

    Don't assign the result of `mrb_funcall()` directly to `regs`

    There are two reasons:

      - If the mruby call stack is extended, the `ci` variable may become invalid.
      - The C language does not specify the order in which the left-hand and right-hand sides of an assignment expression are evaluated.
        Therefore, if the mruby data stack is extended, `ci->stack` may become invalid.

diff --git a/src/vm.c b/src/vm.c
index 9b03789db..a1f272a52 100644
--- a/src/vm.c
+++ b/src/vm.c
@@ -3112,7 +3112,9 @@ RETRY_TRY_BLOCK:
       {                                                                     \
         mrb_value arg = mrb_int_value(mrb, c);                              \
         mrb_sym mid = MRB_OPSYM(op_name);                                   \
-        regs[a] = mrb_funcall_argv(mrb, regs[a], mid, 1, &arg);             \
+        mrb_value v = mrb_funcall_argv(mrb, regs[a], mid, 1, &arg);         \
+        ci = mrb->c->ci;                                                    \
+        regs[a] = v;                                                        \
         mrb_gc_arena_restore(mrb, ai);                                      \
       }                                                                     \
       break;                                                                \
